// LED Blink — the "Hello World" of electronics.
// Blinks an LED wired to digital pin 13 once every second.

const int LED_PIN = 13; // change this if you wired the LED to a different pin

void setup() {
  pinMode(LED_PIN, OUTPUT); // tell the Arduino this pin will send power OUT, not read it
}

void loop() {
  digitalWrite(LED_PIN, HIGH); // turn the LED on (pin outputs 5V)
  delay(1000);                 // wait 1000 milliseconds (1 second)
  digitalWrite(LED_PIN, LOW);  // turn the LED off (pin outputs 0V)
  delay(1000);                 // wait 1 second before repeating
}
